import{z as l,x as i,o as d,c as A,q as c,j as t,D as E,d as a,s,S as r,b as o}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"命令注入","description":"","frontmatter":{"title":"命令注入","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/command-injection.md","filePath":"cs/command-injection.md","lastUpdated":1791413859000}'),B={name:"cs/command-injection.md"};function p(m,e,h,u,f,_){const n=i("Mermaid");return d(),A("div",null,[e[2]||(e[2]=c('<h1 id="命令注入" tabindex="-1">命令注入 <a class="header-anchor" href="#命令注入" aria-label="Permalink to &quot;命令注入&quot;">​</a></h1><div class="epigraph"><p>把用户字符串拼进壳命令，等于把元字符交给壳。防御是不经过壳：参数数组、类型化 API，而不是黑名单转义。</p><footer>—— 据 CWE-78；对照[注入](/cs/injection-boundary)</footer></div><p>上一课<a href="/cs/path-traversal-upload">路径</a>是文件系统语法。缺口是<strong>壳语法</strong>。主干注入课已禁止拼接 SQL；本课落到 exec。不给命令 payload。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>把路径拼进系统命令字符串。<code>system(s)</code> 等价 <code>/bin/sh -c s</code>：整串先过壳文法，<code>; | &amp; $()</code>、反引号、<code>&gt;</code> 都在数据位被重新解释，空格触发词切分，引号配对错让数据溢出到语法位。控制通道与数据通道共用一个串，是注入类缺陷的通式——<a href="/cs/injection-boundary">SQL 注入</a>与路径穿越是它的两个实例。缺口是 API：参数向量、无壳执行。</p><h3 id="模板与邮件" tabindex="-1">模板与邮件 <a class="header-anchor" href="#模板与邮件" aria-label="Permalink to &quot;模板与邮件&quot;">​</a></h3><p>不只是 shell：任何会调壳的库都算。发信包装器拼 <code>sendmail</code> 命令行、构建脚本起子进程、包装器调 <code>find -exec</code>，都在应用与 exec 之间插了一层壳。参数即便进了 argv，被调程序自己再拼壳（仓库 hook、<code>ssh RemoteCommand</code>）仍会复发。</p><p><span class="marginnote">术语翻译：壳（shell）就是帮你把一行文本「翻译成程序调用」的解释器，它认得分号、管道 <code>|</code>、反引号这些元字符。命令注入的本质，就是用户数据被这层翻译器当成了语法来执行，而不是当数据收下。</span></p><p><span class="marginnote">CWE-78。禁止注入教程。XXE 下一课是 XML 解释器。壳注入与参数注入是两族：后者是 argv 数据被下游当选项，<code>--</code> 分隔符只治后者。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照参数化查询：语句与参数分离。exec 侧是 <code>execve</code>/<code>posix_spawn</code> 的数组世界——路径、argv、envp 全是向量，壳没有入口。必须重定向或管道时在进程内做：<code>dup2</code>、<code>pipe</code> 代替 <code>&gt;</code> 与 <code>|</code>；PATH 钉成绝对路径；envp 用最小集，防 <code>BASH_ENV</code> 一类经环境进壳。下一课 XXE。</p><p><span class="marginnote">直觉类比：拼字符串交给壳，像把你的话写给传话人、由他自行理解后转述——传话人可能自由发挥；<code>execve</code> 的参数数组则像填标准表格，每个格子语义固定，中间没有任何人再「解读」你的内容。</span></p>',13)),(d(),t(r,null,{default:E(()=>[s(n,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20STR%5B%22%E6%8B%BC%E6%8E%A5%E5%AD%97%E7%AC%A6%E4%B8%B2%22%5D%20--%3E%20SH%5B%22%E5%A3%B3%E5%86%8D%E8%A7%A3%E6%9E%90%22%5D%0A%20%20ARG%5B%22%E5%8F%82%E6%95%B0%E5%90%91%E9%87%8F%22%5D%20--%3E%20EXEC%5B%22%E6%97%A0%E5%A3%B3%E6%89%A7%E8%A1%8C%22%5D%0A"})]),fallback:E(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=o("h2",{id:"机制",tabindex:"-1"},[a("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=o("p",null,[a("壳是图灵完备的解释器，拼接等于把用户输入当代码注入该解释器——与 XSS 同构。转义清单永不完备：元字符集合随实现变化，引号内的二次展开（反引号、"),o("code",null,"$( )"),a("）仍可能发生。最小特权限制爆炸半径，不改注入成立：进程主动执行了外人命令。Shellshock（CVE-2014-6271）点名壳自身也是攻击面：环境变量经 bash 函数导出成可执行体。残余失败模式是参数注入：以 "),o("code",null,"-"),a(" 开头的路径被下游程序当选项，靠 "),o("code",null,"--"),a(" 分隔或白名单校验。XXE 用 XML 特性读文件或出站。")],-1)),(d(),t(r,null,{default:E(()=>[s(n,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E7%94%A8%E6%88%B7%E8%BE%93%E5%85%A5%3A%20%E4%B8%80%E4%B8%AA%E6%96%87%E4%BB%B6%E5%90%8D%22%5D%20--%3E%20CAT%5B%22%E8%B7%AF%E5%BE%84%20A%3A%20%E6%8B%BC%E8%BF%9B%E5%91%BD%E4%BB%A4%E5%AD%97%E7%AC%A6%E4%B8%B2%22%5D%0A%20%20CAT%20--%3E%20SH%5B%22%2Fbin%2Fsh%20%E8%A7%A3%E6%9E%90%E6%95%B4%E4%B8%B2%22%5D%0A%20%20SH%20--%3E%20META%5B%22%E5%85%83%E5%AD%97%E7%AC%A6%E8%A2%AB%E5%BD%93%E8%AF%AD%E6%B3%95%E6%89%A7%E8%A1%8C%22%5D%0A%20%20IN%20--%3E%20VEC%5B%22%E8%B7%AF%E5%BE%84%20B%3A%20%E6%94%BE%E8%BF%9B%20argv%20%E6%95%B0%E7%BB%84%22%5D%0A%20%20VEC%20--%3E%20EXEC%5B%22execve%20%E7%9B%B4%E6%8E%A5%E4%BC%A0%E7%BB%99%E7%9B%AE%E6%A0%87%E7%A8%8B%E5%BA%8F%22%5D%0A%20%20EXEC%20--%3E%20DATA%5B%22%E8%BE%93%E5%85%A5%E5%8F%AA%E6%98%AF%E6%95%B0%E6%8D%AE%2C%20%E6%97%A0%E5%A3%B3%E5%8F%AF%E6%B3%A8%E5%85%A5%22%5D%0A"})]),fallback:E(()=>[...e[1]||(e[1]=[a(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=c('<p><span class="marginnote">数字实例：参数注入的经典翻车是把用户起的文件名叫 <code>-rf</code>——程序明明只想要个名字，却把开头的 <code>-</code> 认成选项。约定 <code>--</code> 表示「选项到此为止，后面全是普通参数」；它只治参数注入，治不了经过壳的命令注入，因为后者根本轮不到下游程序说话。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>零 payload。壳元字符是语法，不是「过滤分号」能穷尽的清单；黑名单转义是在错误的层修文法问题。XXE 下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>路径是文件名语法；命令注入是壳语法。</li><li>永不经过壳；用参数数组。</li><li>转义黑名单不够。</li><li>下一课 XXE。</li><li>出处：CWE-78；<a href="/cs/injection-boundary">injection-boundary</a>。</li></ul>',5))])}const b=l(B,[["render",p]]);export{D as __pageData,b as default};
